  ui_story_5050_50500101_11_dialog_content = "Comparado aos simuladores de batalha tradicionais, acredito que este simulador de treinamento cooperativo tem o potencial de treinar de forma abrangente as habilidades de todos.",
  ui_story_5050_50500101_12_dialog_content = "É por isso que gostaria de convidar todos a experimentar - vocês também estarão me ajudando com os testes ao mesmo tempo!",
