  ui_story_5050_50500101_29_dialog_content = "Todos precisam explorar o mapa e completar o estágio <color=#FFB400>missões</color>. Seu objetivo é alcançar a linha de chegada e reivindicar todos os suprimentos e recompensas!",
  ui_story_5050_50500101_30_dialog_content = "Estará equipado com um comunicador para esta simulação, permitindo-lhe comunicar remotamente.",
