  ui_story_5050_50500101_32_dialog_content = "D-Não foque muito nesses pequenos detalhes, não vai ser tão simples quanto você imagina.",
  ui_story_5050_50500101_33_dialog_content = "Ambas as equipes precisarão trabalhar juntas para operar certos mecanismos em áreas especiais. Este será o momento em que sua capacidade de trabalhar em conjunto será testada!",
  ui_story_5050_50500101_34_dialog_content = "Tudo ainda soa um pouco ambíguo para mim. Vamos entrar no simulador e dar uma olhada por nós mesmos.",
