  ui_story_5050_50500205_1_dialog_content = "A saída desta etapa deve estar à frente.",
  ui_story_5050_50500205_2_dialog_content = "Anatoli, você está desenhando um mapa?",
  ui_story_5050_50500205_3_dialog_content = "Sim, fiz um registro completo do terreno atual.",
