  ui_story_5050_50500302_3_dialog_content = "... Você não precisa parar por minha causa. Eu estou bem.",
  ui_story_5050_50500302_4_dialog_content = "Eu não disse que era por sua causa.",
  ui_story_5050_50500302_5_dialog_content = "Você não precisa ser tão atencioso, capitão Leo. A tarefa em mãos é crucial, embora eu aprecie sua gentileza. Tosse...!",
