  ui_story_5050_50500302_7_dialog_content = "O que você quer dizer com isso? Você está tentando dizer que sou um fardo?",
  ui_story_5050_50500302_8_dialog_content = "Oh! Acalme-se, todos, por favor.",
  ui_story_5050_50500302_9_dialog_content = "Suas intenções aqui são todas boas. Somos todos filhos do Deus da Luz, então, por favor, vamos manter a harmonia.",
  ui_story_5050_50500302_10_dialog_content = "...",
  ui_story_5050_50500302_11_dialog_content = "Tudo bem. Eu sei que você não pode forçar os outros a agirem contra sua vontade. Vamos continuar.",
  ui_story_5050_50500303_1_dialog_content = "Graças aos céus, parece que estamos prestes a chegar à saída.",
  ui_story_5050_50500303_2_dialog_content = "...",
  ui_story_5050_50500303_3_dialog_content = "(Leo tem uma personalidade poderosa, e Zhao pode ocasionalmente se tornar bastante sensível devido ao seu estímulo físico, embora ele pareça ter os pés no chão na maior parte do tempo.)",
  ui_story_5050_50500303_4_dialog_content = "(A atmosfera tem estado um pouco tensa desde agora. Espero que esses dois não acabem se confrontando de frente.)",
  ui_story_5050_50500303_5_dialog_content = "Hah, logo chegaremos ao fim do desafio. Embora a dificuldade possa ter aumentado, somos mais do que capazes de sair desta triunfantes.",
  ui_story_5050_50500303_6_dialog_content = "No entanto, o combate também é uma forma de arte, e a vitória não pode ser conquistada simplesmente por aqueles que avançam ferozmente para a batalha, lança na mão. Sem alguém por trás deles para traçar estratégias, a derrota é inevitável.",
  ui_story_5050_50500303_7_dialog_content = "Joseph, Zhao, cooperamos lindamente lá fora.",
  ui_story_5050_50500303_8_dialog_content = "Não há necessidade de ser excessivamente pessimista ou autocrítico devido a questões com as quais não podemos lidar no momento.",
  ui_story_5050_50500303_9_dialog_content = "Ainda há muitas outras coisas que podemos fazer.",
  ui_story_5050_50500303_10_dialog_content = "Certo. Obrigado.",
  ui_story_5050_50500303_11_dialog_content = "Eu apenas exagerei um pouco, por favor, não pense muito nisso.",
  ui_story_5050_50500303_12_dialog_content = "Por que eu deveria? Somos todos companheiros de equipe aqui, por que se preocupar com assuntos tão insignificantes?",
  ui_story_5050_50500303_13_dialog_content = "Não sabemos se haverá novos desafios na próxima etapa. Precisamos ter cuidado enquanto avançamos.",
  ui_story_5050_50500401_1_dialog_content = "Cidade de Gannon?",
  ui_story_5050_50500401_2_dialog_content = "Parece tão.",
  ui_story_5050_50500401_3_dialog_content = "Se bem me lembro, você e Axelia são ambos nativos de Gannon, correto?",
  ui_story_5050_50500401_4_dialog_content = "Sua inteligência é impecável como sempre. Na verdade, nascemos na cidade de Gannon.",
  ui_story_5050_50500401_5_dialog_content = "Assim como eu.",
  ui_story_5050_50500401_6_dialog_content = "Portanto, nós três devemos ter bastante vantagem neste mapa.",
  ui_story_5050_50500401_7_dialog_content = "Sim. Este lugar certamente está cheio de muitas memórias.",
  ui_story_5050_50500401_8_dialog_content = "Também foi aqui que conheci Yingel e Sean.",
  ui_story_5050_50500401_9_dialog_content = "Embora a vida fosse monótona naquela época, ainda parecia que éramos uma pequena família.",
  ui_story_5050_50500401_10_dialog_content = "Você está a fim disso, Axelia?",
  ui_story_5050_50500401_11_dialog_content = "Não se preocupe. Estou bem.",
  ui_story_5050_50500401_12_dialog_content = "Vamos então. Nós não devemos fazer Leo e sua equipe espera muito tempo.",
  ui_story_5050_50500401_13_dialog_content = "...",
  ui_story_5050_50500402_1_dialog_content = "Você ainda consegue acompanhar?",
  ui_story_5050_50500402_2_dialog_content = "Certo!",
  ui_story_5050_50500402_3_dialog_content = "... Eu vou ficar bem.",
  ui_story_5050_50500402_4_dialog_content = "As simulações de batalha do Eclipsite são bastante normais, eu nunca imaginei que essas missões estranhas seriam tão complicadas.",
  ui_story_5050_50500402_5_dialog_content = "Tenho observado o local desde que entramos e notei que os waypoints são bem diferentes dos encontros da vida real.",
  ui_story_5050_50500402_6_dialog_content = "Embora o conceito de missões, recursos, cooperação e assim por diante existam em situações reais de combate, eles não têm uma natureza mecânica tão rígida.",
  ui_story_5050_50500402_7_dialog_content = "Como assim?",
  ui_story_5050_50500402_8_dialog_content = "Na minha opinião pessoal, Gronru copiou e implementou alguns elementos de jogabilidade abrangentes de um determinado videogame.",
  ui_story_5050_50500402_9_dialog_content = "Não estou surpreso... Certamente soa como algo que ela faria.",
  ui_story_5050_50500402_10_dialog_content = "E eu especulo que adicionar esses mecanismos complexos ao simulador de batalha pode colocar uma carga maior nos corpos dos testadores.",
  ui_story_5050_50500402_11_dialog_content = "Especialmente testadores com um nível mais baixo de aptidão física.",
  ui_story_5050_50500402_12_dialog_content = "É apenas minha teoria, mas o desempenho de Axelia tem falhado e acho que ela é mais capaz do que isso.",
  ui_story_5050_50500402_13_dialog_content = "Impressionante. Eu nunca teria sido capaz de pegar isso...",
  ui_story_5050_50500402_14_dialog_content = "Axelia, você gostaria de sair do simulador por um tempo? Não queremos que este teste afete seu desempenho no Exercício Militar Conjunto real...",
  ui_story_5050_50500402_15_dialog_content = "Não é tão sério assim.",
  ui_story_5050_50500402_16_dialog_content = "Não vai afetar o exercício, tenho certeza disso.",
  ui_story_5050_50500402_17_dialog_content = "Tudo bem então, vamos tomar uma decisão rápida e seguir em frente o mais rápido possível.",
  ui_story_5050_50500403_1_dialog_content = "Eu posso ver a saída.",
  ui_story_5050_50500403_2_dialog_content = "Concluímos a maioria dos desafios e, no momento, parece que a quarta etapa está chegando ao fim.",
  ui_story_5050_50500403_3_dialog_content = "Estamos aqui há tanto tempo. PlayerName e os outros devem estar ficando impacientes esperando por nós.",
  ui_story_5050_50500403_4_dialog_content = "Não há nada que possamos fazer sobre isso. Embora existam apenas seis estágios, este teste tomou muito mais tempo do que eu esperava.",
  ui_story_5050_50500403_5_dialog_content = "Também, Vice sabe muito sobre mecânica, então PlayerName e os outros podem passar por esses estágios mais rápido do que nós.",
  ui_story_5050_50500403_6_dialog_content = "Está tudo bem, vamos seguir nosso próprio ritmo.",
  ui_story_5050_50500403_7_dialog_content = "Desculpe por fazer todo mundo se preocupar comigo esse tempo todo...",
  ui_story_5050_50500403_8_dialog_content = "Tudo o que importa é que você está bem.",
  ui_story_5050_50500403_9_dialog_content = "Talvez possamos nos juntar a eles no próximo estágio.",
  ui_story_5050_50500501_1_dialog_content = "Parece que voltamos ao tema cogovernado da Cidade Baixa nesta fase.",
  ui_story_5050_50500501_2_dialog_content = "Yingel, está tudo indo bem do seu lado?",
  ui_story_5050_50500501_3_dialog_content = "Sim, está tudo bem para nós.",
  ui_story_5050_50500501_4_dialog_content = "Só gostaria de confirmar uma coisa com vocês... Algum de vocês está se sentindo mal?",
  ui_story_5050_50500501_5_dialog_content = "... Por que você pergunta?",
  ui_story_5050_50500501_6_dialog_content = "Axelia tem se sentido mal esse tempo todo.",
  ui_story_5050_50500501_7_dialog_content = "Eu suspeito que os mecanismos excessivamente complexos deste simulador colocam um fardo maior em pessoas com constituições físicas fracas.",
  ui_story_5050_50500501_8_dialog_content = "Então é isso que está errado.",
  ui_story_5050_50500501_9_dialog_content = "Hmm, na verdade eu também tinha notado.",
  ui_story_5050_50500501_10_dialog_content = "Oi pessoal!",
  ui_story_5050_50500501_11_dialog_content = "Desculpe, estou fazendo um teste no simulador, acabei de ouvir sua conversa.",
  ui_story_5050_50500501_12_dialog_content = "Eu realmente não considerei o efeito físico que o simulador poderia ter em seus usuários...",
  ui_story_5050_50500501_13_dialog_content = "Mas parece que a maioria das deduções de Anatoli estão corretas.",
  ui_story_5050_50500501_14_dialog_content = "Esta é uma questão relativamente significativa. Talvez Zhao e Axelia deveria sair e descansar?",
  ui_story_5050_50500501_15_dialog_content = "Não há necessidade.",
  ui_story_5050_50500501_16_dialog_content = "V-você é realmente tão determinado?",
  ui_story_5050_50500501_17_dialog_content = "Eu tenho fé no meu corpo. Vou pedir para descansar quando necessário.",
  ui_story_5050_50500501_18_dialog_content = "Digo o mesmo.",
  ui_story_5050_50500501_19_dialog_content = "Estamos chegando ao fim. Vamos acabar com isso.",
  ui_story_5050_50500501_20_dialog_content = "Se eles insistem, vamos respeitar as opiniões das partes envolvidas.",
  ui_story_5050_50500501_21_dialog_content = "Ok, também estarei de olho na situação de todos o tempo todo.",
  ui_story_5050_50500501_22_dialog_content = "Esta fase parece ter uma seção de desbloqueio cooperativo. Leo, contamos com você.",
  ui_story_5050_50500501_23_dialog_content = "Não se preocupe, vamos resolver isso de uma só vez.",
  ui_story_5050_50500502_1_dialog_content = "Parece que esta fase tem um tema Undercity.",
  ui_story_5050_50500502_2_dialog_content = "Parece que vamos precisar Leo e os outros para nos ajudar a desvendar o caminho à frente antes que possamos passar.",
  ui_story_5050_50500502_3_dialog_content = "Certo. Vamos fazer uma pausa aqui enquanto esperamos.",
  ui_story_5050_50500502_4_dialog_content = "Suspirar...",
  ui_story_5050_50500502_5_dialog_content = "(Axelia parece muito cansado.)",
  ui_story_5050_50500502_6_dialog_content = "(Eu nunca esperei que o pequeno auroriano do orfanato, tantos anos atrás, crescesse e se tornasse tão forte.)",
  ui_story_5050_50500502_7_dialog_content = "(Olhando para trás, parece que foi ontem.)",
  ui_story_5050_50500502_8_dialog_content = "... Pensando em algo?",
  ui_story_5050_50500502_9_dialog_content = "Apenas lembrando do passado.",
  ui_story_5050_50500502_10_dialog_content = "Memórias de infância?",
  ui_story_5050_50500502_11_dialog_content = "Por que diz isso?",
  ui_story_5050_50500502_12_dialog_content = "Não subestime o alcance da minha rede de inteligência. Você e Axelia se conhecem desde crianças. Eu sei tudo sobre isso.",
  ui_story_5050_50500502_13_dialog_content = "Sim, nós nos conhecemos desde muito jovens.",
  ui_story_5050_50500502_14_dialog_content = "Lutar ao lado de um velho conhecido em quem você realmente confia é algo invejável, sob certo ponto de vista.",
  ui_story_5050_50500502_15_dialog_content = "Você tem alguém assim?",
  ui_story_5050_50500502_16_dialog_content = "...",
  ui_story_5050_50500502_17_dialog_content = "Vamos parar de conversar por enquanto, não queremos acordá-la.",
  ui_story_5050_50500503_1_dialog_content = "Embora isso realmente não se qualifique como treinamento de batalha intensivo, essa simulação ainda requer um esforço físico significativo. Você está bem?",
  ui_story_5050_50500503_2_dialog_content = "Estou bem. Zhao?",
  ui_story_5050_50500503_3_dialog_content = "Estou bem, também.",
  ui_story_5050_50500503_4_dialog_content = "<size=45>?!</size>",
  ui_story_5050_50500503_5_dialog_content = "O que é tudo isso?",
  ui_story_5050_50500503_6_dialog_content = "Caramba! Desculpe!",
  ui_story_5050_50500503_7_dialog_content = "Este é um bug conhecido... Às vezes, o mapa errado é carregado.",
  ui_story_5050_50500503_8_dialog_content = "Mas não se preocupe, isso não afetará seu progresso!",
  ui_story_5050_50500503_9_dialog_content = "Eu notei antes que existem lacunas óbvias nas conexões entre algumas salas nos palcos.",
  ui_story_5050_50500503_10_dialog_content = "Mas não vi nenhuma dessas lacunas nos caminhos onde você pode encontrar Eclipsites.",
  ui_story_5050_50500503_11_dialog_content = "Eu estou supondo que esses quartos são todos gerados aleatoriamente, correto?",
  ui_story_5050_50500503_12_dialog_content = "<size=45>!!!</size>",
  ui_story_5050_50500503_13_dialog_content = "Não tente adivinhar aleatoriamente os pensamentos do designer!",
  ui_story_5050_50500503_14_dialog_content = "É confidencial! Confidencial!",
  ui_story_5050_50500503_15_dialog_content = "Zhao, seus poderes de observação são extremamente aguçados.",
  ui_story_5050_50500503_16_dialog_content = "Você realmente é digno de sua reputação como estrategista incomparável da Illumina, sendo capaz de captar detalhes tão minuciosos.",
  ui_story_5050_50500503_17_dialog_content = "Isso é um pouco exagerado. Acabei de me acostumar a observar detalhes no campo de batalha.",
  ui_story_5050_50500503_18_dialog_content = "Tudo bem! Não se preocupe com esses pequenos detalhes, apenas passe para a próxima etapa rapidamente! A última etapa não será fácil!",
  ui_story_5050_50500503_19_dialog_content = "Hehe, ainda não vai levar a melhor sobre nós! Vamos!",
  ui_story_5050_50500504_1_dialog_content = "Parece que estamos prestes a chegar à fase final.",
  ui_story_5050_50500504_2_dialog_content = "A fase final não será fácil... Coloquem a cabeça no jogo, pessoal.",
  ui_story_5050_50500504_3_dialog_content = "Yingel, como você está fazendo no seu lado? Você já alcançou a saída?",
  ui_story_5050_50500504_4_dialog_content = "Estamos quase lá.",
  ui_story_5050_50500504_5_dialog_content = "É Axelia OK?",
  ui_story_5050_50500504_6_dialog_content = "Não se preocupe, acabei de descansar e me sinto muito melhor agora.",
  ui_story_5050_50500504_7_dialog_content = "Estou em plena forma e pronto para encarar o desafio final de frente.",
  ui_story_5050_50500504_8_dialog_content = "Haha, fico feliz em saber disso!",
  ui_story_5050_50500504_9_dialog_content = "Nos vemos na fase final!",
  ui_story_5050_50500504_10_dialog_content = "Ok, vamos seguir em frente rapidamente.",
  ui_story_5050_50500601_1_dialog_content = "...",
  ui_story_5050_50500601_2_dialog_content = "O que está errado, Leo? Você está se sentindo bem?",
  ui_story_5050_50500601_3_dialog_content = "Ninguém nunca me perguntou isso antes... Fique tranquilo, minha fortaleza não conhece limites.",
  ui_story_5050_50500601_4_dialog_content = "Capitão Leo, é porque estamos em Lumopolis?",
  ui_story_5050_50500601_5_dialog_content = "Você é de Lumópolis. Este mapa deve parecer muito familiar para você.",
  ui_story_5050_50500601_6_dialog_content = "... Haha, e eu nunca tive alguém adivinhando o que eu estava pensando tão facilmente antes.",
  ui_story_5050_50500601_7_dialog_content = "Você está certo, não posso negar, nasci aqui.",
  ui_story_5050_50500601_8_dialog_content = "Lumopolis me deu muito, mas também tirou muito de mim.",
  ui_story_5050_50500601_9_dialog_content = "Um nobre banido lançado de Uptown para uma área infinitamente próxima da Noite Eterna. Mesmo se você morresse, você não passaria de um cadáver em decomposição, lamentado por ninguém.",
  ui_story_5050_50500601_10_dialog_content = "Naturalmente, tive muitas experiências inesquecíveis, mas elas também mudaram lentamente a minha forma de pensar.",
  ui_story_5050_50500601_11_dialog_content = "Leo...",
  ui_story_5050_50500601_12_dialog_content = "...",
  ui_story_5050_50500601_13_dialog_content = "Eu não queria divagar assim. Tudo o que você precisa saber é que atualmente tenho apenas um objetivo - lutar contra os Eclipsites com todos aqueles dispostos a ficar ao meu lado.",
  ui_story_5050_50500601_14_dialog_content = "Podemos conversar sobre outros assuntos à vontade quando tivermos algum tempo livre no futuro.",
  ui_story_5050_50500601_15_dialog_content = "Excelente. Eu adoraria ouvir mais.",
  ui_story_5050_50500601_16_dialog_content = "Leo, você também já chegou em Lumopolis por lá?",
  ui_story_5050_50500601_17_dialog_content = "Sim, estamos no mapa Uptown.",
  ui_story_5050_50500601_18_dialog_content = "Devemos nos encontrar perto do fim. Continuem, pessoal.",
  ui_story_5050_50500601_19_dialog_content = "Você também. Fique seguro.",
  ui_story_5050_50500601_20_dialog_content = "Vamos embora!",
  ui_story_5050_50500602_1_dialog_content = "Isso é... Lumópolis?",
  ui_story_5050_50500602_2_dialog_content = "Eu nunca estive aqui antes.",
  ui_story_5050_50500602_3_dialog_content = "A julgar pelo layout aqui, deve ser Lower Lumopolis. Certamente tem um estilo único.",
  ui_story_5050_50500602_4_dialog_content = "Nós três estamos estacionados em Illumina. Não tivemos oportunidade de nos familiarizar com Lumopolis.",
  ui_story_5050_50500602_5_dialog_content = "Devemos aproveitar esta oportunidade para dar uma olhada.",
  ui_story_5050_50500602_6_dialog_content = "Lumópolis...",
  ui_story_5050_50500602_7_dialog_content = "Anatoli, você tem algo contra Lumopolis?",
  ui_story_5050_50500602_8_dialog_content = "Eu me considero um centrista nessa questão. Embora o vínculo entre Illumina e Lumopolis seja um tanto delicado, não me inclino para nenhum dos lados.",
  ui_story_5050_50500602_9_dialog_content = "Todos nós temos os mesmos objetivos e esperanças de um amanhã melhor. Por que usar tais facções para semear hostilidade e preconceito deliberadamente?",
  ui_story_5050_50500602_10_dialog_content = "Esse é exatamente o tipo de resposta que eu esperava de você.",
  ui_story_5050_50500602_11_dialog_content = "Não importa de onde você é ou a qual facção você pertence, todos nós agora temos apenas um objetivo comum.",
  ui_story_5050_50500602_12_dialog_content = "Talvez olhar ocasionalmente para um problema de uma perspectiva diferente possa tornar as coisas mais fáceis.",
  ui_story_5050_50500602_13_dialog_content = "A fase final, deve ser desafiadora.",
  ui_story_5050_50500602_14_dialog_content = "Sim. Eu me pergunto se haverá algum desafio de estágio especial...",
  ui_story_5050_50500602_15_dialog_content = "Vamos!",
  ui_story_5050_50500603_1_dialog_content = "Leo! Finalmente estamos juntos novamente.",
  ui_story_5050_50500603_2_dialog_content = "Tenho que admitir que trabalhamos muito bem juntos, caso contrário não teríamos chegado à linha de chegada tão rapidamente.",
  ui_story_5050_50500603_3_dialog_content = "Mas eu não entendi muito bem algumas das missões. Essas foram dores de cabeça.",
  ui_story_5050_50500603_4_dialog_content = "Foi tudo graças aos esforços conjuntos de todos que conseguimos.",
  ui_story_5050_50500603_5_dialog_content = "Axelia, como você está indo?",
  ui_story_5050_50500603_6_dialog_content = "Estou me sentindo cem por cento.",
  ui_story_5050_50500603_7_dialog_content = "Louvado seja o Deus da Luz pelas bênçãos. É o poder de nossa confiança mútua que tornou nossa jornada tão bem-sucedida.",
  ui_story_5050_50500603_8_dialog_content = "Uau! Ótimo trabalho! Parabéns por alcançar a linha de chegada!",
  ui_story_5050_50500603_9_dialog_content = "Gostou do treinamento?",
  ui_story_5050_50500603_10_dialog_content = "Pode ser diferente do treinamento prático a que você está acostumado, mas também ajuda a trabalhar uma variedade de habilidades, tornando-o igualmente gratificante.",
  ui_story_5050_50500603_11_dialog_content = "Esta foi uma experiência rara para nos tornarmos mais familiarizados com as habilidades uns dos outros por meio de uma cooperação próxima.",
  ui_story_5050_50500603_12_dialog_content = "heheh mais um classico Gronru produção, desenvolvida ao longo de vários dias e noites sem dormir!",
  ui_story_5050_50500603_13_dialog_content = "Outra pequena sugestão - talvez você deva retrabalhar a senha controlada por voz no mapa Colossus.",
  ui_story_5050_50500603_14_dialog_content = "Huh? Oh...",
  ui_story_5050_50500603_15_dialog_content = "<size=45>O quê?!?! Eu não mudei?!</size>",
  ui_story_5050_50500603_16_dialog_content = "<size=45>Th-Isso foi apenas algo que adicionei aleatoriamente durante a depuração!</size>",
  ui_story_5050_50500603_17_dialog_content = "Está tudo bem... Apenas alguns de nós sabem a senha agora.",
  ui_story_5050_50500603_18_dialog_content = "E então há apenas Vice, Carleen, e PlayerName a seguir.",
  ui_story_5050_50500603_19_dialog_content = "Você não está me fazendo sentir melhor.",
  ui_story_5050_50500603_20_dialog_content = "Ahem... De qualquer forma, bom trabalho a todos. Não deixe as equipes restantes esperarem muito - preparem-se...",
  ui_story_5050_50500603_21_dialog_content = "<color=#e8d9bb>Rumble, rumble...</color>",
  ui_story_5050_50500603_22_dialog_content = "Isso é um terremoto?",
  ui_story_5050_50500603_23_dialog_content = "... O que está acontecendo? Por que o sistema de repente relatou um erro?!",
  ui_story_5050_50500603_24_dialog_content = "Cuidado com o passo, pessoal!",
  ui_story_5050_50500603_25_dialog_content = "<size=45>?!</size>",
  ui_story_5050_50500603_26_dialog_content = "O mapa está mudando.",
  ui_story_5050_50500603_27_dialog_content = "Eles são todos os estágios em que estivemos antes. Há algo de errado com o sistema?",
  ui_story_5050_50500603_28_dialog_content = "Aaah! Pessoal, por favor, esperem um momento — estou consertando!",
  ui_story_5050_50500603_29_dialog_content = "<color=#e8d9bb>Alguns minutos depois...</color>",
  ui_story_5050_50500603_30_dialog_content = "Ufa... Deve estar tudo bem agora.",
  ui_story_5050_50500603_31_dialog_content = "Desculpe, pode ter havido alguns pequenos erros deixados na última parte.",
  ui_story_5050_50500603_32_dialog_content = "Acho que não depurei o estágio final completamente o suficiente.",
  ui_story_5050_50500603_33_dialog_content = "Essa coisa à frente também é um dos seus insetos?",
  ui_story_5050_50500603_34_dialog_content = "Huh? Que?",
  ui_story_5050_50500603_35_dialog_content = "<anim type=Shake><size=45>Graa! Graaah!</size></anim>",
