  ui_story_5050_50500604_9_dialog_content = "Nossas vitórias são baseadas no esforço de cada um de nossos companheiros.",
  ui_story_5050_50500604_10_dialog_content = "Não é todo dia que se ouve Leo fazer um discurso tão emocional.",
  ui_story_5050_50500604_11_dialog_content = "Eu estava apenas expressando meus sentimentos.",
  ui_story_5050_50500604_12_dialog_content = "Ao enfrentar missões tão complexas, uma única pessoa é como uma mosca sem cabeça sem uma equipe trabalhando em conjunto por uma causa comum.",
  ui_story_5050_50500604_13_dialog_content = "Também fico muito grato pela ajuda de todos.",
  ui_story_5050_50500604_14_dialog_content = "Eu apenas fiz o que achei certo.",
  ui_story_5050_50500604_15_dialog_content = "Neste momento, aceitemos esta calorosa bondade com paz em nossos corações. May o Deus da Luz abençoe todos os nossos companheiros de confiança e nós.",
  ui_story_5050_50500604_16_dialog_content = "Então, qual jogo serviu de base para essa simulação?",
  ui_story_5050_50500604_17_dialog_content = "Na verdade, era a Espada do... quero dizer, eu mesmo a desenhei!",
